     if code == 0:
         return StepResult("sync_landing", True, "Landing pages synced")
     else:
         return StepResult("sync_landing", False, "Sync failed", details=(stderr or "")[:500])


 def run_pipeline(
     lang_pair: str,
     level: str | None,
     module_num: int | None,
     steps: list[str]
 ) -> bool:
     """Run the full pipeline."""

     print("\n" + "="*60)
     print("🚀 Learn Ukrainian Pipeline")
     print("="*60)
